async function loadUsage() {
    try {
        const data = await api('/subscription-usage');

        // Top bar widget
        const subType = data.subscription_type || 'unknown';
        document.getElementById('subType').textContent = subType.charAt(0).toUpperCase() + subType.slice(1);
        const todayAdmin = data.admin_today ? data.admin_today.total_requests : 0;
        document.getElementById('subTodayCount').textContent = todayAdmin;

        // Modal details
        document.getElementById('usageSubType').textContent = subType.charAt(0).toUpperCase() + subType.slice(1);
        document.getElementById('usageModel').textContent = data.model || '-';

        // Admin requests
        document.getElementById('usageTodayAdmin').textContent = todayAdmin;
        document.getElementById('usageTodayChat').textContent = data.admin_today ? data.admin_today.chat_requests : 0;
        document.getElementById('usageTodayCode').textContent = data.admin_today ? data.admin_today.code_requests : 0;

        // Today from stats-cache
        document.getElementById('usageTodayMessages').textContent = data.today_messages || 0;
        document.getElementById('usageTodaySessions').textContent = data.today_sessions || 0;
        document.getElementById('usageTodayTokens').textContent = formatTokens(data.today_tokens_total || 0);
        document.getElementById('usageTodayTools').textContent = data.today_tools || 0;

        // Totals
        document.getElementById('usageTotalMsgs').textContent = formatNumber(data.total_messages || 0);
        document.getElementById('usageTotalSessions').textContent = data.total_sessions || 0;

        // Rate limit section
        const rl = data.rate_limits || {};
        const rlSection = document.getElementById('rateLimitSection');
        const hitsToday = rl.hits_today || 0;
        const hitsTotal = rl.hits_total || 0;

        // Always show rate limit section
        rlSection.style.display = 'block';
        document.getElementById('rlTodayCount').textContent = `${hitsToday} ${t('rate_limit_times')}`;
        document.getElementById('rlTotalCount').textContent = `${hitsTotal} ${t('rate_limit_times')}`;
        document.getElementById('rlLastHit').textContent = rl.last_hit_time
            ? `${t('rate_limit_at')} ${rl.last_hit_time}`
            : '-';

        const rlStatusEl = document.getElementById('rlStatus');
        if (hitsToday > 0) {
            rlStatusEl.innerHTML = `<span style="color:var(--yellow);">⚠️ ${t('rate_limit_warning')}</span>`;
            rlSection.style.borderColor = 'rgba(251,191,36,0.3)';
            rlSection.style.background = 'rgba(251,191,36,0.05)';
        } else {
            rlStatusEl.innerHTML = `<span style="color:var(--accent);">✅ ${t('rate_limit_ok')}</span>`;
            rlSection.style.borderColor = 'var(--border)';
            rlSection.style.background = 'transparent';
        }

        // Sub widget warning badge
        const subWidget = document.querySelector('.sub-widget');
        const existingBadge = document.getElementById('rlBadge');
        if (existingBadge) existingBadge.remove();
        if (hitsToday > 0) {
            const badge = document.createElement('span');
            badge.id = 'rlBadge';
            badge.style.cssText = 'font-size:0.65rem;color:var(--yellow);margin-left:4px;';
            badge.textContent = `⚠️ ${hitsToday}`;
            badge.title = `Rate limit: ${hitsToday}x ${t('rate_limit_at')} ${rl.last_hit_time || ''}`;
            subWidget.appendChild(badge);
        }

        // Daily activity list
        const daily = data.daily_activity || [];
        const list = document.getElementById('usageDailyList');
        if (daily.length > 0) {
            list.innerHTML = daily.reverse().map(d => {
                const date = d.date || '';
                const msgs = d.messageCount || 0;
                const tools = d.toolCallCount || 0;
                const sessions = d.sessionCount || 0;
                return `<div class="usage-day-row">
                    <span>${date}</span>
                    <span style="color:var(--text-secondary);">${sessions} sess</span>
                    <span>${msgs} msgs</span>
                    <span style="color:var(--text-secondary);">${tools} tools</span>
                </div>`;
            }).join('');
        } else {
            list.innerHTML = `<div style="text-align:center;color:var(--text-secondary);padding:12px;">${t('no_data')}</div>`;
        }
    } catch (e) {
        console.error('Usage load error:', e);
    }
}

function formatTokens(n) {
    if (n >= 1000000) return (n / 1000000).toFixed(1) + 'M';
    if (n >= 1000) return (n / 1000).toFixed(1) + 'K';
    return String(n);
}

function formatNumber(n) {
    if (n >= 1000) return (n / 1000).toFixed(1) + 'K';
    return String(n);

